import { describe, it, expect, jest, beforeEach, afterEach } from '@jest/globals';
import { CurriculumWebConnector } from '../../../src/services/connectors/curriculumWebConnector';

// Mock global fetch
global.fetch = jest.fn() as jest.MockedFunction<typeof fetch>;

describe('Test Connector Timeout Issue', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    // Always reject to prevent real network calls
    (global.fetch as jest.Mock).mockRejectedValue(new Error('Mocked fetch error'));
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should handle errors without timing out', async () => {
    const connector = new CurriculumWebConnector();
    const results = await connector.search({ query: 'test', gradeLevel: 1 });
    expect(results).toEqual([]);
  }, 5000); // 5 second timeout
});